export async function publicProducts(db){const templates=await settings(db,'vehicle_templates',[]);const templateProducts=templates.filter(t=>t.active&&t.fileKey).map(t=>({id:t.ruleId,name:t.make+' '+t.model+' vector',path:'/satin/shop/products/'+t.ruleId,ruleId:t.ruleId,active:true,stock:null,artwork:false,images:t.previewKey?['/api/template-preview?id='+t.id]:[],digital:true}));const saved=await settings(db,'product_catalog',[]);return defaults.map(p=>saved.find(s=>s.id===p.id)||p).concat(saved.filter(s=>!defaults.some(p=>p.id===s.id)),templateProducts).map(normalizeProduct).filter(p=>p.active);}
async function settings(db,k,fallback){const r=await db.prepare('SELECT value FROM site_settings WHERE key = ?').bind(k).first();return r?JSON.parse(r.value):fallback;}
async function save(db,k,v){await db.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').bind(k,JSON.stringify(v),new Date().toISOString()).run();}
async function input(r){const s=await r.text();if(s.length>400000)throw Error('Request too large');return JSON.parse(s);}
