 if(path==='/api/admin/product-image-upload'){if(request.method!=='POST'||!env.FILES)return json({error:'Image storage unavailable'},503);const fd=await request.formData(),f=fd.get('file');if(!f||typeof f.arrayBuffer!=='function'||!f.size||f.size>10000000||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('Choose PNG, JPG or WebP up to 10 MB');const bytes=new Uint8Array(await f.arrayBuffer());const valid=f.type==='image/png'?bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71:f.type==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:new TextDecoder().decode(bytes.slice(0,4))==='RIFF'&&new TextDecoder().decode(bytes.slice(8,12))==='WEBP';if(!valid)throw Error('The file does not match its image type');const id=crypto.randomUUID(),key='products/'+id;await env.FILES.put(key,bytes,{httpMetadata:{contentType:f.type}});return json({url:'/api/product-image?id='+id});}
 if(path==='/api/product-image'){if(request.method!=='GET')return json({error:'Method not allowed'},405);const id=url.searchParams.get('id');if(!/^[a-f0-9-]{36}$/.test(id||''))throw Error('Invalid image');const saved=await settings(db,'product_catalog',[]);if(!isAdmin(request)&&!saved.some(p=>p.active&&p.images?.includes('/api/product-image?id='+id))&&!await publishedImage(env,'/api/product-image?id='+id))return json({error:'Image unavailable'},404);const file=await env.FILES?.get('products/'+id);if(!file)return json({error:'Image unavailable'},404);return new Response(file.body,{headers:{'Content-Type':file.httpMetadata.contentType,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});}

